const row=$input.first().json;
const patient_id=String(row.patient_id||'').trim();
const patient_email=String(row.patient_email||'').trim();
const day_number=parseInt(row.day_number)||1;
const symptom_score=parseFloat(row.symptom_score)||0;
const screen_hrs=parseFloat(row.screen_hrs)||0;
const sleep_hrs=parseFloat(row.sleep_hrs)||0;
const exercise_attempted=String(row.exercise_attempted||'no').toLowerCase().trim();
const vomiting=String(row.vomiting||'no').toLowerCase()==='yes';
const vision_changes=String(row.vision_changes||'no').toLowerCase()==='yes';
const notes=String(row.notes||'').trim();
if(!patient_id)throw new Error('Missing patient_id');
if(!patient_email)throw new Error('Missing patient_email');
if(symptom_score<0||symptom_score>10)throw new Error('symptom_score must be 0-10');
return[{json:{patient_id,patient_email,day_number,symptom_score,screen_hrs,sleep_hrs,exercise_attempted,vomiting,vision_changes,notes,received_at:new Date().toISOString()}}];

const checkin=$('Input Validator').first().json;
const pacer=$input.first().json;
const output=pacer.output||pacer;
const stageBadgeColor={1:'#C0431A',2:'#E8640A',3:'#D4A520',4:'#0D6E58',5:'#1A3460'}[output.protocol_stage]||'#888880';
const activityIcon={'rest':'🛌','light':'🚶','moderate':'🏃','full':'✅'}[output.activity_level]||'📋';
return[{json:{patient_id:checkin.patient_id,patient_email:checkin.patient_email,day_number:checkin.day_number,symptom_score:checkin.symptom_score,activity_level:output.activity_level||'rest',activity_label:output.activity_label||'Stage 1 — Complete Rest',recommendation:output.recommendation||'',protocol_stage:output.protocol_stage||1,protocol_source:output.protocol_source||'CDC HEADS UP',next_step:output.next_step||'',encouragement:output.encouragement||'',stage_color:stageBadgeColor,activity_icon:activityIcon,generated_at:new Date().toISOString()}}];
